/**
 * Catalogue initial YEN Career Bridge : données de référence (pas de données
 * personnelles). Source unique utilisée par scripts/build-seed.ts pour générer
 * supabase/seed.sql. Le catalogue reste ensuite administrable depuis l'interface.
 *
 * Niveaux : critères observables propres à chaque compétence, dans l'ordre
 * [débutant, intermédiaire, avancé, expert].
 */

export type Level = "debutant" | "intermediaire" | "avance" | "expert";
export type Importance = "obligatoire" | "importante" | "souhaitee";

export interface SkillSeed {
  slug: string;
  name: string;
  tier: "fondamentale" | "avancee";
  category?: "technique" | "transversale" | "outil";
  criteria: [string, string, string, string];
  aliases?: string[];
}

export interface OccupationSeed {
  slug: string;
  title: string;
  description: string;
  education: string;
  skills: [slug: string, level: Level, importance: Importance][];
}

export interface QuestionSeed {
  type: "choix_unique" | "choix_multiple" | "reponse_courte" | "etude_de_cas";
  prompt: string;
  skill: string;
  points?: number;
  options?: [label: string, correct: boolean][];
  accepted?: string[];
  rubric?: { criterion: string; points: number }[];
  explanation: string;
}

export interface AssessmentSeed {
  slug: string;
  title: string;
  description: string;
  level: Level;
  duration: number;
  questions: QuestionSeed[];
}

export interface DomainSeed {
  slug: string;
  name: string;
  icon: string;
  short: string;
  description: string;
  tools: string[];
  certifications: string[];
  projectTypes: string[];
  progression: string;
  skills: SkillSeed[];
  occupations: OccupationSeed[];
  assessments: AssessmentSeed[];
}

